#pragma once

#include <Nexyl/Base/Error.h>
#include <Nexyl/Base/Flags.h>
#include <Nexyl/Base/Result.h>
#include <Nexyl/Base/Span.h>
#include <Nexyl/Base/Types.h>
#include <Nexyl/Containers/StringView.h>
#include <Nexyl/Memory/IAllocator.h>
#include <Nexyl/Reflection/TypeId.h>

// The reflection model shares this header because its parts describe one another (rule HDR-9 allows tightly
// coupled types in one header). Tables of these types are generated by the header tool, never written by hand.

namespace Nexyl::Reflection {

/// What a type is, and so which parts of its TypeInfo apply.
/// @since 0.1
enum class TypeKind : u8 {
    /// `bool`.
    Bool,
    /// `char`.
    Character,
    /// A signed integer.
    SignedInteger,
    /// An unsigned integer.
    UnsignedInteger,
    /// `f32` or `f64`.
    FloatingPoint,
    /// An enumeration: `enumValues` lists its values; `element` is its underlying integer type.
    Enum,
    /// A class or struct with reflected fields: `fields`, `base`.
    Record,
    /// A class known by identity only (`@opaque`, or a pure interface): no fields.
    Opaque,
    /// A built-in array `T[N]`: `element`, `count`.
    FixedArray,
    /// Containers::String: `stringOperations`.
    String,
    /// Containers::Array<T>: `element`, `arrayOperations`.
    Array,
    /// Containers::HashMap<K, V>: `element` is the key type, `value` the value type, `mapOperations`.
    HashMap,
    /// Containers::Handle<T>: `element` is `T`. Stored as two u32, index then generation.
    Handle,
};

/// Properties of a type from its documentation tags (docs/NEXYL_ARCHITECTURE.md, section 8.5).
/// @since 0.1
enum class TypeFlag : u8 {
    /// `@hidden`: not shown in the editor, not exposed to scripts.
    Hidden,
    /// `@noscript`: not exposed to scripts.
    NoScript,
};

/// Properties of a field, from C++ access and documentation tags (sections 8.4 and 8.5).
/// @since 0.1
enum class FieldFlag : u8 {
    /// A public data member: editable and visible to scripts.
    Public,
    /// `@transient`: not serialized, not hashed.
    Transient,
    /// `@presentation`: serialized, not part of simulation state.
    Presentation,
    /// `@readonly`: visible but not editable.
    ReadOnly,
    /// `@hidden`: not shown in the editor, not exposed to scripts.
    Hidden,
    /// `@noscript`: not exposed to scripts.
    NoScript,
};

/// One data member of a record.
/// @threadsafety safe
/// @since 0.1
struct FieldInfo {
    /// The member's name.
    const char* name = "";
    /// The member's type; resolve it with TypeRegistry::Find.
    TypeId type;
    /// Byte offset of the member in the record.
    usize offset = 0;
    /// Access and tags.
    Flags<FieldFlag> flags;
    /// The summary of the member's documentation comment.
    const char* description = "";
    /// `@units`, or empty.
    const char* units = "";
    /// `@category`, or empty.
    const char* category = "";
    /// `@renamed-from`, or empty.
    const char* renamedFrom = "";
    /// `@range` was given.
    bool hasRange = false;
    /// The lower end of `@range`.
    f64 rangeMinimum = 0.0;
    /// The upper end of `@range`.
    f64 rangeMaximum = 0.0;
    /// `@step`, or zero.
    f64 step = 0.0;
};

/// One value of an enumeration.
/// @threadsafety safe
/// @since 0.1
struct EnumValueInfo {
    /// The enumerator's name.
    const char* name = "";
    /// Its value, sign-extended.
    i64 value = 0;
    /// The summary of its documentation comment.
    const char* description = "";
    /// `@renamed-from`, or empty.
    const char* renamedFrom = "";
    /// `@hidden` was given.
    bool hidden = false;
};

/// How objects of a type are created and destroyed in raw memory. A null function means the operation is
/// not available for the type.
/// @threadsafety safe
/// @since 0.1
struct TypeLifecycle {
    /// Default-constructs an object at `object`.
    void (*construct)(void* object) = nullptr;
    /// Destroys the object at `object`.
    void (*destruct)(void* object) = nullptr;
    /// Copy-constructs an object at `destination` from the one at `source`.
    void (*copy)(void* destination, const void* source) = nullptr;
    /// Move-constructs an object at `destination` from the one at `source`.
    void (*move)(void* destination, void* source) = nullptr;
};

/// Type-erased access to a Containers::Array.
/// @threadsafety compatible
/// @since 0.1
struct ArrayOperations {
    /// Returns the number of elements.
    usize (*size)(const void* array) = nullptr;
    /// Returns the address of an element.
    void* (*at)(void* array, usize index) = nullptr;
    /// Returns the address of an element.
    const void* (*atConst)(const void* array, usize index) = nullptr;
    /// Resizes, default-constructing new elements. An array without an allocator takes `fallback`.
    Result<void, Error> (*resize)(void* array, usize size, Memory::IAllocator& fallback) = nullptr;
};

/// Type-erased access to a Containers::String.
/// @threadsafety compatible
/// @since 0.1
struct StringOperations {
    /// Returns the text.
    Containers::StringView (*view)(const void* string) = nullptr;
    /// Replaces the text. A string without an allocator takes `fallback`.
    Result<void, Error> (*assign)(void* string, Containers::StringView text, Memory::IAllocator& fallback) = nullptr;
};

/// Type-erased access to a Containers::HashMap.
/// @threadsafety compatible
/// @since 0.1
struct MapOperations {
    /// Returns the number of entries.
    usize (*size)(const void* map) = nullptr;
    /// Calls `visitor` for every entry in insertion order.
    void (*visit)(const void* map, void (*visitor)(void* context, const void* key, const void* value),
                  void* context) = nullptr;
    /// Inserts or replaces an entry, moving from `key` and `value`. A map without an allocator takes `fallback`.
    Result<void, Error> (*set)(void* map, void* key, void* value, Memory::IAllocator& fallback) = nullptr;
};

/// Everything reflection knows about one type. Generated tables and the built-in types provide constant
/// instances; a TypeRegistry finds them by identity or name.
/// @threadsafety safe
/// @since 0.1
struct TypeInfo {
    /// The canonical name, for example `Nexyl::Math::Vec3` or `u32`.
    const char* name = "";
    /// The identity.
    TypeId id;
    /// `sizeof`.
    usize size = 0;
    /// `alignof`.
    usize alignment = 0;
    /// What the type is.
    TypeKind kind = TypeKind::Opaque;
    /// Tags.
    Flags<TypeFlag> flags;
    /// The summary of the type's documentation comment.
    const char* description = "";
    /// `@category`, or empty.
    const char* category = "";
    /// `@renamed-from`, or empty.
    const char* renamedFrom = "";
    /// The schema version from `@version`; 1 without the tag. Archives store it with the data.
    u32 version = 1;
    /// Record: the reflected base class, or null.
    TypeId base;
    /// Record: the type's own data members, in declaration order (the base's are in the base's TypeInfo).
    Span<const FieldInfo> fields;
    /// Enum: the values, in declaration order.
    Span<const EnumValueInfo> enumValues;
    /// FixedArray, Array, Handle: the element type; HashMap: the key type; Enum: the underlying type.
    TypeId element;
    /// HashMap: the value type.
    TypeId value;
    /// FixedArray: the number of elements.
    usize count = 0;
    /// How objects are created and destroyed.
    TypeLifecycle lifecycle;
    /// Record with private fields: confirms their offsets on a default-constructed object, because the compiler
    /// cannot check them at compile time; null otherwise, or when the type has no accessible default
    /// constructor. Tests call it (docs/NEXYL_ARCHITECTURE.md, section 8.7).
    bool (*checkLayout)() = nullptr;
    /// Array: element access.
    const ArrayOperations* arrayOperations = nullptr;
    /// String: text access.
    const StringOperations* stringOperations = nullptr;
    /// HashMap: entry access.
    const MapOperations* mapOperations = nullptr;
};

/// The reflected types of one module, as the header tool generates them.
/// @threadsafety safe
/// @since 0.1
struct TypeTable {
    /// The module's name.
    const char* module = "";
    /// The types: the module's own, and the built-in instantiations its fields use.
    Span<const TypeInfo* const> types;
};

} // namespace Nexyl::Reflection
